import { clsx, type ClassValue } from 'clsx';
import { extendTailwindMerge } from 'tailwind-merge';
import { densityMergeConfig } from './density-merge';

const twMerge = extendTailwindMerge(densityMergeConfig);

/** Joins class names and resolves Tailwind conflicts (last one wins), density utilities included. */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Teaches tailwind-merge the density utilities from @gntik-ai/tokens (density.css), so
 * `cn('h-control', 'h-10')` and `px-control … px-0` resolve like any other Tailwind conflict.
 * Shared by `cn()` and the `tv()` instance.
 */
export const densityMergeConfig = {
  extend: {
    classGroups: {
      h: [{ h: ['control-sm', 'control', 'control-lg', 'item', 'tab', 'chip', 'token', 'row'] }],
      w: [{ w: ['control-sm', 'control', 'control-lg'] }],
      size: [{ size: ['control-sm', 'control', 'control-lg'] }],
      px: [{ px: ['control-sm', 'control', 'control-lg', 'field'] }],
      ps: [{ ps: ['field'] }],
      py: [{ py: ['cell', 'bar'] }],
      gap: [{ gap: ['tight'] }],
    },
  },
};

/** Mirrors a directional glyph (chevron, arrow) in right-to-left text. */
export const RTL_FLIP = 'rtl:-scale-x-100';

const DIRECTIONAL = /^(?:Chevrons?(?:Left|Right)|Arrow(?:Left|Right)\w*|Move(?:Left|Right)|Panel(?:Left|Right)\w*|Undo\d?|Redo\d?|Corner\w+(?:Left|Right)|Indent\w*|Outdent\w*)$/;

/**
 * True for lucide icons that point along the inline axis (ChevronLeft, ArrowRight,
 * PanelLeftClose…), which mirror under RTL. Detected from the icon's displayName.
 */
export function isDirectionalIcon(icon: unknown): boolean {
  const name = (icon as { displayName?: unknown } | null | undefined)?.displayName;
  return typeof name === 'string' && DIRECTIONAL.test(name);
}

/** `RTL_FLIP` for a directional icon, else undefined. */
export const rtlIconClass = (icon: unknown) => (isDirectionalIcon(icon) ? RTL_FLIP : undefined);

import { createTV } from 'tailwind-variants';
import { densityMergeConfig } from './density-merge';

export { type VariantProps } from 'tailwind-variants';

/** `tv()` with tailwind-merge aware of the density utilities (h-control, px-control…). */
export const tv = createTV({ twMergeConfig: densityMergeConfig });
